draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, 50 + 20 * Math.sin(t + i), 0, 2 * Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, 20 + 10 * Math.cos(t + i), 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.restore();
}
